import { useState,useEffect } from 'react'; // Step 1: import useStart and useEffect
import Axios from 'axios';

function App() {
  //useState
const [users, setUsers] = useState([]); // Step 2 create useStatect
useEffect(()=>{                         // Step 3 create useEffect & copy Axios insed useEffect
Axios.get("http://localhost:3001/")
 .then(res=>{
  setUsers(res.data); // Display the setUsers for useState
 });
},[]);

const createUser=()=>{
  Axios.post("http://localhost:3001/",{
  name:'Rocky',
  age:8,
  email: 'rockstart@yahoo.com',
  })
}

  return (
    <div className="card">
      {users.map(user=>{
      return(
        <ul>
          <li>{user.name}</li>
          <li>{user.age}</li>
          <li>{user.email}</li>
        </ul>
      );
 })}
    <div>
      <input type="text" placeholder='Name' />
      <input type="number" placeholder='Age'/>
      <input type="text" placeholder="Email"/>
      <button onClick={createUser}>Create User</button>
    </div>

    </div>
  );
}

export default App;
